:"ед. заказа","unit_note":"Единица закупки в таблице отдельно не задана; объём/упаковка сохранены в названии."},{"source_row":179,"source_key":"ketch:order-product:r179","name":"Добрый кола 0,25 стекло 12шт.","category":"Вода,Соки","supplier_key":"кока кола","supplier_name":"Кока Кола","unit_price":"671.00","unit":"ед. заказа","unit_note":"Единица закупки в таблице отдельно не задана; объём/упаковка сохранены в названии."},{"source_row":180,"source_key":"ketch:order-product:r180","name":"Добрый кола без сахара 0,25 12шт.","category":"Вода,Соки","supplier_key":"кока кола","supplier_name":"Кока Кола","unit_price":"671.00","unit":"ед. заказа","unit_note":"Единица закупки в таблице отдельно не задана; объём/упаковка сохранены в названии."},{"source_row":181,"source_key":"ketch:order-product:r181","name":"Добрый Лимон-Лайм 0,25 12шт.","category":"Вода,Соки","supplier_key":"кока кола","supplier_name":"Кока Кола","unit_price":"671.00","unit":"ед. заказа","unit_note":"Единица закупки в таблице отдельно не задана; объём/упаковка сохранены в названии."}]$data$::jsonb) LOOP
  IF EXISTS(SELECT 1 FROM public.order_products WHERE source_key=p->>'source_key') THEN CONTINUE; END IF;
  sid:=NULL;
  IF p->>'supplier_name' IS NOT NULL THEN
   SELECT id INTO STRICT sid FROM public.order_suppliers WHERE lower(btrim(name))=lower(btrim(p->>'supplier_name'));
  END IF;
  SELECT count(*),min(id::text)::uuid INTO n,pid FROM public.order_products WHERE lower(btrim(name))=lower(btrim(p->>'name')) AND supplier_id IS NOT DISTINCT FROM sid;
  IF n>1 THEN RAISE EXCEPTION 'Multiple existing products: %',p->>'name'; END IF;
  IF n=1 THEN
   IF EXISTS(SELECT 1 FROM public.order_products WHERE id=pid AND source_key IS NOT NULL) THEN RAISE EXCEPTION 'Conflicting product source key: %',p->>'name'; END IF;
   UPDATE public.order_products SET source_key=p->>'source_key' WHERE id=pid;
  ELSE
   INSERT INTO public.order_products(source_key,name,category,supplier_id,unit_price,unit) VALUES(p->>'source_key',p->>'name',p->>'category',sid,(p->>'unit_price')::numeric,'ед. заказа');
  END IF;
 END LOOP;
END $seed$;
COMMIT;
